record.field:
av = 0

c_f_i = 0



for header_lines in records:

  con_header = env['consignment_header'].search([('id', '=', header_lines.consignment_id.id)],limit=1)

  if con_header:

    delivery_term = env['delivery_term_charge'].search([('delivery_terms_id', '=', con_header.delivery_term.id), ('tax_appicable', '=', True)]) 

    if delivery_term:

      for valid_terms in delivery_term:

        header_charges = env['consignment_charge_h'].search([('consignment_id', '=', con_header.id), ('charge_group', '=', 'Charges'), ('charge_name', '=', valid_terms.name)],limit=1)

        if header_charges:

          c_f_i += header_charges.amount



      av = con_header.total_amount + c_f_i

      title = "Calculate Assessable Value"

      message = "Assessable Value: " + str(av)



      action = {

                'type': 'ir.actions.client',

                'tag': 'display_notification',

                'params': {'title': title,'message': message,'sticky': True,}

                } 

      break
